298	__global__ void reduce_band_to_tridiagonal(
299	    const float* input, float* reflectors, float* diagonal, float* off_diagonal,
300	    float* taus, int n) {
301	  extern __shared__ float shared[];
302	  float* matrix = shared;
303	  const int pitch = n + 4;
304	  float* v = matrix + n * pitch;
305	  float* y = v + n;
306	  float* reduction = y + n;
307	  const int tid = static_cast<int>(threadIdx.x);
308	  const int64_t batch_offset = static_cast<int64_t>(blockIdx.x) * n * n;
309	
310	  const int load_warp = tid >> 5;
311	  const int load_lane = tid & 31;
312	  for (int row = load_warp; row < n; row += blockDim.x >> 5) {
313	    for (int col = load_lane; col <= row; col += 32) {
314	      matrix[row * pitch + col] = input[batch_offset + row * n + col];
315	    }
316	  }
317	  __syncthreads();
318	
319	  for (int column = 0; column < n - 2; ++column) {
320	    const int base = column + 1;
321	    const int size = n - base;
322	    float local_norm = 0.0f;
323	    for (int index = tid + 1; index < size; index += blockDim.x) {
324	      const float value = matrix[(base + index) * pitch + column];
325	      local_norm += value * value;
326	    }
327	    const float norm_sum = block_sum_leader(local_norm, reduction);
328	
329	    if (tid == 0) {
330	      const float alpha = matrix[base * pitch + column];
331	      const float tail_norm = sqrtf(norm_sum);
332	      float beta = alpha;
333	      float tau = 0.0f;
334	      float inverse = 0.0f;
335	      if (tail_norm != 0.0f) {
336	        beta = -copysignf(hypotf(alpha, tail_norm), alpha);
337	        tau = (beta - alpha) / beta;
338	        inverse = 1.0f / (alpha - beta);
339	      }
340	      diagonal[static_cast<int64_t>(blockIdx.x) * n + column] =
341	          matrix[column * pitch + column];
342	      off_diagonal[static_cast<int64_t>(blockIdx.x) * n + column] = beta;
343	      taus[static_cast<int64_t>(blockIdx.x) * n + column] = tau;
344	      reduction[0] = tau;
345	      reduction[1] = inverse;
346	    }
347	    __syncthreads();
348	
349	    const float tau = reduction[0];
350	    const float inverse = reduction[1];
351	    for (int index = tid; index < size; index += blockDim.x) {
352	      v[index] = index == 0
353	          ? 1.0f
354	          : matrix[(base + index) * pitch + column] * inverse;
355	    }
356	    __syncthreads();
357	
358	    constexpr int kDotWidth = 4;
359	    const int row = tid / kDotWidth;
360	    const int dot_lane = tid & (kDotWidth - 1);
361	    float local_dot = 0.0f;
362	    if (row < size) {
363	      float sum = 0.0f;
364	      for (int inner = dot_lane; inner < size; inner += kDotWidth) {
365	        const float element = row >= inner
366	            ? matrix[(base + row) * pitch + base + inner]
367	            : matrix[(base + inner) * pitch + base + row];
368	        sum += element * v[inner];
369	      }
370	      const unsigned int mask = __activemask();
371	      sum += __shfl_down_sync(mask, sum, 2, kDotWidth);
372	      sum += __shfl_down_sync(mask, sum, 1, kDotWidth);
373	      if (dot_lane == 0) {
374	        const float y_value = tau * sum;
375	        y[row] = y_value;
376	        local_dot = v[row] * y_value;
377	      }
378	    }
379	    const float dot = block_sum_leader(local_dot, reduction);
380	    if (tid == 0) {
381	      reduction[0] = dot * (-0.5f * tau);
382	    }
383	    __syncthreads();
384	    const float correction = reduction[0];
385	
386	    const int update_warp = tid >> 5;
387	    const int update_lane = tid & 31;
388	    for (int row = update_warp; row < size; row += blockDim.x >> 5) {
389	      const float row_v = v[row];
390	      const float row_y = y[row] + (2.0f * correction) * row_v;
391	      for (int col = update_lane; col <= row; col += 32) {
392	        matrix[(base + row) * pitch + base + col] -=
393	            row_v * y[col] + row_y * v[col];
394	      }
395	    }
396	
397	    for (int index = tid; index < size; index += blockDim.x) {
398	      const float stored = index == 0
399	          ? off_diagonal[static_cast<int64_t>(blockIdx.x) * n + column]
400	          : v[index];
401	      reflectors[batch_offset + column * n + base + index] = stored;
402	    }
403	    __syncthreads();
404	  }
405	
406	  if (tid == 0) {
407	    const int64_t vector_offset = static_cast<int64_t>(blockIdx.x) * n;
408	    diagonal[vector_offset + n - 2] = matrix[(n - 2) * pitch + n - 2];
409	    diagonal[vector_offset + n - 1] = matrix[(n - 1) * pitch + n - 1];
410	    off_diagonal[vector_offset + n - 2] =
411	        matrix[(n - 1) * pitch + n - 2];
412	    off_diagonal[vector_offset + n - 1] = 0.0f;
413	    taus[vector_offset + n - 2] = 0.0f;
414	    taus[vector_offset + n - 1] = 0.0f;
415	  }
416	}
