418	__global__ void reduce_global_to_tridiagonal(
419	    float* matrix, float* diagonal, float* off_diagonal, float* taus, int n) {
420	  extern __shared__ float shared[];
421	  float* v = shared;
422	  float* y = v + n;
423	  float* reduction = y + n;
424	  const int tid = static_cast<int>(threadIdx.x);
425	  const int64_t batch_offset = static_cast<int64_t>(blockIdx.x) * n * n;
426	  const int64_t vector_offset = static_cast<int64_t>(blockIdx.x) * n;
427	
428	  for (int column = 0; column < n - 2; ++column) {
429	    const int base = column + 1;
430	    const int size = n - base;
431	    float local_norm = 0.0f;
432	    for (int index = tid + 1; index < size; index += blockDim.x) {
433	      const float value = matrix[batch_offset + (base + index) * n + column];
434	      local_norm += value * value;
435	    }
436	    const float norm_sum = block_sum_leader(local_norm, reduction);
437	
438	    if (tid == 0) {
439	      const float alpha = matrix[batch_offset + base * n + column];
440	      const float tail_norm = sqrtf(norm_sum);
441	      float beta = alpha;
442	      float tau = 0.0f;
443	      float inverse = 0.0f;
444	      if (tail_norm != 0.0f) {
445	        beta = -copysignf(hypotf(alpha, tail_norm), alpha);
446	        tau = (beta - alpha) / beta;
447	        inverse = 1.0f / (alpha - beta);
448	      }
449	      diagonal[vector_offset + column] =
450	          matrix[batch_offset + column * n + column];
451	      off_diagonal[vector_offset + column] = beta;
452	      taus[vector_offset + column] = tau;
453	      reduction[0] = tau;
454	      reduction[1] = inverse;
455	    }
456	    __syncthreads();
457	
458	    const float tau = reduction[0];
459	    const float inverse = reduction[1];
460	    for (int index = tid; index < size; index += blockDim.x) {
461	      v[index] = index == 0
462	          ? 1.0f
463	          : matrix[batch_offset + (base + index) * n + column] * inverse;
464	    }
465	    __syncthreads();
466	
467	    constexpr int kDotWidth = 8;
468	    const int dot_group = tid / kDotWidth;
469	    const int dot_lane = tid & (kDotWidth - 1);
470	    for (int row = dot_group; row < size;
471	         row += static_cast<int>(blockDim.x) / kDotWidth) {
472	      float sum = 0.0f;
473	      for (int inner = dot_lane; inner < size; inner += kDotWidth) {
474	        const float element = row >= inner
475	            ? matrix[batch_offset + (base + row) * n + base + inner]
476	            : matrix[batch_offset + (base + inner) * n + base + row];
477	        sum += element * v[inner];
478	      }
479	      const unsigned int mask = __activemask();
480	      #pragma unroll
481	      for (int offset = kDotWidth / 2; offset > 0; offset >>= 1) {
482	        sum += __shfl_down_sync(mask, sum, offset, kDotWidth);
483	      }
484	      if (dot_lane == 0) {
485	        y[row] = tau * sum;
486	      }
487	    }
488	    __syncthreads();
489	
490	    float local_dot = 0.0f;
491	    for (int index = tid; index < size; index += blockDim.x) {
492	      local_dot += v[index] * y[index];
493	    }
494	    const float dot = block_sum_leader(local_dot, reduction);
495	    if (tid == 0) {
496	      reduction[0] = dot * (-0.5f * tau);
497	    }
498	    __syncthreads();
499	    const float correction = reduction[0];
500	    for (int index = tid; index < size; index += blockDim.x) {
501	      y[index] += correction * v[index];
502	    }
503	    __syncthreads();
504	
505	    const int update_lane = tid & 31;
506	    const int update_warp = tid >> 5;
507	    for (int update_row = update_warp; update_row < size;
508	         update_row += static_cast<int>(blockDim.x) / 32) {
509	      for (int update_col = update_lane; update_col <= update_row;
510	           update_col += 32) {
511	        matrix[batch_offset + (base + update_row) * n + base + update_col] -=
512	            v[update_row] * y[update_col] +
513	            y[update_row] * v[update_col];
514	      }
515	    }
516	    __syncthreads();
517	
518	    for (int index = tid; index < size; index += blockDim.x) {
519	      matrix[batch_offset + (base + index) * n + column] = index == 0
520	          ? off_diagonal[vector_offset + column]
521	          : v[index];
522	    }
523	    __syncthreads();
524	  }
525	
526	  if (tid == 0) {
527	    diagonal[vector_offset + n - 2] =
528	        matrix[batch_offset + (n - 2) * n + n - 2];
529	    diagonal[vector_offset + n - 1] =
530	        matrix[batch_offset + (n - 1) * n + n - 1];
531	    off_diagonal[vector_offset + n - 2] =
532	        matrix[batch_offset + (n - 1) * n + n - 2];
533	    off_diagonal[vector_offset + n - 1] = 0.0f;
534	    taus[vector_offset + n - 2] = 0.0f;
535	    taus[vector_offset + n - 1] = 0.0f;
536	  }
537	}
