539	template <int kEigenpairsPerBlock, int kGroupWidth, int kVectorPitch,
540	          bool kColumnMajorReflectors>
541	__global__ void tridiagonal_eigh_and_backtransform(
542	    const float* reflectors, const float* input_diagonal,
543	    const float* input_off_diagonal, const float* taus, float* vectors,
544	    float* values, int* info, int n) {
545	  constexpr int kThreads = kEigenpairsPerBlock * kGroupWidth;
546	  extern __shared__ float shared[];
547	  float* d = shared;
548	  float* e = d + n;
549	  float* tile_vectors = e + n;
550	  float* tile_factors = tile_vectors + n * kVectorPitch;
551	  __shared__ float lower_bounds[kThreads];
552	  __shared__ float upper_bounds[kThreads];
553	
554	  const int tid = static_cast<int>(threadIdx.x);
555	  const int tiles_per_matrix = (n + kEigenpairsPerBlock - 1) /
556	      kEigenpairsPerBlock;
557	  const int matrix = static_cast<int>(blockIdx.x) / tiles_per_matrix;
558	  const int tile = static_cast<int>(blockIdx.x) % tiles_per_matrix;
559	  const int eigen_slot = tid / kGroupWidth;
560	  const int group_lane = tid & (kGroupWidth - 1);
561	  const int eigen_index = tile * kEigenpairsPerBlock + eigen_slot;
562	  const int64_t vector_offset = static_cast<int64_t>(matrix) * n;
563	  const int64_t matrix_offset = vector_offset * n;
564	  for (int index = tid; index < n; index += blockDim.x) {
565	    d[index] = input_diagonal[vector_offset + index];
566	    e[index] = input_off_diagonal[vector_offset + index];
567	  }
568	  __syncthreads();
569	
570	  float local_low = FLT_MAX;
571	  float local_high = -FLT_MAX;
572	  for (int index = tid; index < n; index += blockDim.x) {
573	    const float radius = (index ? fabsf(e[index - 1]) : 0.0f) +
574	        (index + 1 < n ? fabsf(e[index]) : 0.0f);
575	    local_low = fminf(local_low, d[index] - radius);
576	    local_high = fmaxf(local_high, d[index] + radius);
577	  }
578	  lower_bounds[tid] = local_low;
579	  upper_bounds[tid] = local_high;
580	  __syncthreads();
581	  for (int stride = blockDim.x / 2; stride; stride >>= 1) {
582	    if (tid < stride) {
583	      lower_bounds[tid] = fminf(lower_bounds[tid], lower_bounds[tid + stride]);
584	      upper_bounds[tid] = fmaxf(upper_bounds[tid], upper_bounds[tid + stride]);
585	    }
586	    __syncthreads();
587	  }
588	  const float global_low = lower_bounds[0];
589	  const float global_high = upper_bounds[0];
590	  if (tid == 0 && tile == 0) {
591	    info[matrix] = 0;
592	  }
593	
594	  if (eigen_index < n) {
595	    const unsigned int group_mask = __activemask();
596	    const float margin = 8.0f * FLT_EPSILON *
597	        (1.0f + fmaxf(fabsf(global_low), fabsf(global_high)));
598	    const float pivot_min = 1.0e-20f *
599	        (1.0f + global_high - global_low);
600	    if (group_lane == 0) {
601	      float low = global_low - margin;
602	      float high = global_high + margin;
603	      const int bisection_iterations = n == 176 ? 21 : 24;
604	      for (int iteration = 0; iteration < bisection_iterations; ++iteration) {
605	        const float midpoint = 0.5f * (low + high);
606	        float pivot = d[0] - midpoint;
607	        if (fabsf(pivot) < pivot_min) {
608	          pivot = -pivot_min;
609	        }
610	        int count = pivot < 0.0f;
611	        for (int row = 1; row < n; ++row) {
612	          pivot = d[row] - midpoint - e[row - 1] * e[row - 1] / pivot;
613	          if (fabsf(pivot) < pivot_min) {
614	            pivot = -pivot_min;
615	          }
616	          count += pivot < 0.0f;
617	        }
618	        if (count <= eigen_index) {
619	          low = midpoint;
620	        } else {
621	          high = midpoint;
622	        }
623	      }
624	      const float eigenvalue = 0.5f * (low + high);
625	      lower_bounds[eigen_slot] = eigenvalue;
626	      values[vector_offset + eigen_index] = eigenvalue;
627	    }
628	    __syncwarp(group_mask);
629	    const float eigenvalue = lower_bounds[eigen_slot];
630	
631	    float* factors = tile_factors + eigen_slot;
632	    float* eigenvector = tile_vectors + eigen_slot;
633	    if (group_lane == 0) {
634	      for (int row = 0; row < n; ++row) {
635	        const int pattern = (row * 17 + eigen_index * 13) % 23;
636	        eigenvector[row * kVectorPitch] =
637	            static_cast<float>(pattern - 11) / 11.0f;
638	      }
639	      const int inverse_iterations = n == 176 ? 3 : 2;
640	      for (int iteration = 0; iteration < inverse_iterations; ++iteration) {
641	        const float signed_shift = (iteration & 1) ? 1.0f : -1.0f;
642	        const float shifted_value = eigenvalue + signed_shift *
643	            2.0f * FLT_EPSILON * (1.0f + fabsf(eigenvalue));
644	        factors[0] = d[0] - shifted_value;
645	        if (fabsf(factors[0]) < pivot_min) {
646	          factors[0] = copysignf(pivot_min, factors[0]);
647	        }
648	        for (int row = 1; row < n; ++row) {
649	          const int factor_offset = row * kVectorPitch;
650	          const int vector_offset = row * kVectorPitch;
651	          const float multiplier =
652	              e[row - 1] /
653	              factors[factor_offset - kVectorPitch];
654	          factors[factor_offset] =
655	              d[row] - shifted_value - multiplier * e[row - 1];
656	          if (fabsf(factors[factor_offset]) < pivot_min) {
657	            factors[factor_offset] =
658	                copysignf(pivot_min, factors[factor_offset]);
659	          }
660	          eigenvector[vector_offset] -=
661	              multiplier * eigenvector[vector_offset - kVectorPitch];
662	        }
663	        eigenvector[(n - 1) * kVectorPitch] /=
664	            factors[(n - 1) * kVectorPitch];
665	        for (int row = n - 2; row >= 0; --row) {
666	          const int factor_offset = row * kVectorPitch;
667	          const int vector_offset = row * kVectorPitch;
668	          eigenvector[vector_offset] =
669	              (eigenvector[vector_offset] -
670	               e[row] * eigenvector[vector_offset + kVectorPitch]) /
671	              factors[factor_offset];
672	        }
673	        float norm = 0.0f;
674	        for (int row = 0; row < n; ++row) {
675	          const float value = eigenvector[row * kVectorPitch];
676	          norm += value * value;
677	        }
678	        const float inverse_norm = rsqrtf(norm);
679	        for (int row = 0; row < n; ++row) {
680	          eigenvector[row * kVectorPitch] *= inverse_norm;
681	        }
682	      }
683	    }
684	    __syncwarp(group_mask);
685	
686	    for (int column = n - 3; column >= 0; --column) {
687	      const int base = column + 1;
688	      const int size = n - base;
689	      float partial = group_lane == 0
690	          ? eigenvector[base * kVectorPitch]
691	          : 0.0f;
692	      for (int row = group_lane + 1; row < size; row += kGroupWidth) {
693	        const int64_t reflector_index = kColumnMajorReflectors
694	            ? matrix_offset + column * n + base + row
695	            : matrix_offset + (base + row) * n + column;
696	        partial += reflectors[reflector_index] *
697	            eigenvector[(base + row) * kVectorPitch];
698	      }
699	      for (int offset = kGroupWidth / 2; offset > 0; offset >>= 1) {
700	        partial += __shfl_down_sync(group_mask, partial, offset, kGroupWidth);
701	      }
702	      const float dot = __shfl_sync(group_mask, partial, 0, kGroupWidth);
